namespace RecipeCommunity.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public class RecipeSubmission
{
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
}

using RecipeCommunity.Models;

namespace RecipeCommunity.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes =
    [
        new()
        {
            Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
            Description = "A simple yet delicious pizza with fresh mozzarella and basil.",
            Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
            Steps = ["Preheat oven to 475°F.", "Roll out dough on floured surface.", "Spread crushed tomatoes evenly.", "Tear mozzarella and distribute.", "Bake for 10-12 minutes.", "Top with fresh basil and drizzle olive oil."],
            AverageRating = 4.5, RatingCount = 24
        },
        new()
        {
            Id = 2, Title = "Chicken Tikka Masala", Category = "Indian",
            Description = "Tender chicken in a creamy spiced tomato sauce.",
            Ingredients = ["Chicken breast", "Yogurt", "Garam masala", "Tomato sauce", "Heavy cream", "Onion", "Garlic", "Ginger"],
            Steps = ["Marinate chicken in yogurt and spices for 2 hours.", "Grill or pan-fry chicken until charred.", "Sauté onion, garlic, and ginger.", "Add tomato sauce and simmer.", "Stir in cream and spices.", "Add chicken and simmer 10 minutes."],
            AverageRating = 4.8, RatingCount = 42
        },
        new()
        {
            Id = 3, Title = "Beef Tacos", Category = "Mexican",
            Description = "Seasoned ground beef tacos with fresh toppings.",
            Ingredients = ["Ground beef", "Taco seasoning", "Corn tortillas", "Lettuce", "Tomato", "Cheese", "Sour cream", "Lime"],
            Steps = ["Brown ground beef in a skillet.", "Add taco seasoning and water, simmer.", "Warm tortillas.", "Assemble tacos with beef and toppings.", "Squeeze lime over top."],
            AverageRating = 4.2, RatingCount = 18
        },
        new()
        {
            Id = 4, Title = "Spaghetti Carbonara", Category = "Italian",
            Description = "Creamy pasta with pancetta and parmesan.",
            Ingredients = ["Spaghetti", "Pancetta", "Eggs", "Parmesan cheese", "Black pepper", "Salt"],
            Steps = ["Cook spaghetti al dente.", "Fry pancetta until crispy.", "Whisk eggs with parmesan and pepper.", "Toss hot pasta with pancetta.", "Remove from heat, stir in egg mixture.", "Serve immediately with extra parmesan."],
            AverageRating = 4.6, RatingCount = 31
        },
        new()
        {
            Id = 5, Title = "Pad Thai", Category = "Asian",
            Description = "Stir-fried rice noodles with shrimp and peanuts.",
            Ingredients = ["Rice noodles", "Shrimp", "Eggs", "Bean sprouts", "Peanuts", "Lime", "Fish sauce", "Tamarind paste"],
            Steps = ["Soak rice noodles in warm water.", "Stir-fry shrimp until pink.", "Push aside, scramble eggs.", "Add noodles and sauce.", "Toss with bean sprouts.", "Serve with peanuts and lime."],
            AverageRating = 4.4, RatingCount = 27
        },
        new()
        {
            Id = 6, Title = "Guacamole", Category = "Mexican",
            Description = "Fresh and zesty avocado dip.",
            Ingredients = ["Avocados", "Lime juice", "Cilantro", "Red onion", "Jalapeño", "Tomato", "Salt"],
            Steps = ["Mash avocados to desired consistency.", "Stir in lime juice and salt.", "Fold in diced onion, tomato, and jalapeño.", "Add chopped cilantro.", "Serve immediately with chips."],
            AverageRating = 4.7, RatingCount = 35
        },
        new()
        {
            Id = 7, Title = "Chocolate Chip Cookies", Category = "Desserts",
            Description = "Classic chewy cookies with gooey chocolate chips.",
            Ingredients = ["Butter", "Sugar", "Brown sugar", "Eggs", "Vanilla", "Flour", "Baking soda", "Chocolate chips"],
            Steps = ["Cream butter and sugars.", "Beat in eggs and vanilla.", "Mix in flour and baking soda.", "Fold in chocolate chips.", "Scoop onto baking sheet.", "Bake at 375°F for 9-11 minutes."],
            AverageRating = 4.9, RatingCount = 56
        },
        new()
        {
            Id = 8, Title = "Miso Soup", Category = "Asian",
            Description = "A light and warming Japanese soup.",
            Ingredients = ["Dashi stock", "Miso paste", "Tofu", "Wakame seaweed", "Green onion"],
            Steps = ["Heat dashi stock.", "Dissolve miso paste into broth.", "Add cubed tofu and wakame.", "Simmer gently (do not boil).", "Garnish with sliced green onion."],
            AverageRating = 4.3, RatingCount = 19
        },
        new()
        {
            Id = 9, Title = "Butter Chicken", Category = "Indian",
            Description = "Rich and creamy tomato-based chicken curry.",
            Ingredients = ["Chicken thighs", "Butter", "Tomato purée", "Cream", "Garam masala", "Fenugreek leaves", "Garlic", "Ginger"],
            Steps = ["Marinate chicken in spices and yogurt.", "Grill or bake chicken.", "Make sauce with butter, tomato, and spices.", "Add cream and fenugreek.", "Combine chicken with sauce.", "Simmer and serve with naan."],
            AverageRating = 4.7, RatingCount = 38
        },
        new()
        {
            Id = 10, Title = "Tiramisu", Category = "Desserts",
            Description = "Italian coffee-flavored layered dessert.",
            Ingredients = ["Ladyfingers", "Espresso", "Mascarpone", "Eggs", "Sugar", "Cocoa powder", "Marsala wine"],
            Steps = ["Brew espresso and let cool.", "Whisk egg yolks with sugar.", "Fold in mascarpone.", "Whip egg whites and fold in.", "Dip ladyfingers in espresso.", "Layer with mascarpone mixture, dust with cocoa."],
            AverageRating = 4.8, RatingCount = 44
        }
    ];

    private readonly Dictionary<int, List<int>> _ratings = [];

    public IReadOnlyList<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().Order().ToList();

    public IReadOnlyList<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        if (stars < 1 || stars > 5) return;
        var recipe = GetById(recipeId);
        if (recipe is null) return;

        if (!_ratings.ContainsKey(recipeId))
            _ratings[recipeId] = [];

        _ratings[recipeId].Add(stars);
        recipe.RatingCount = _ratings[recipeId].Count + 20; // include seed ratings
        recipe.AverageRating = Math.Round(
            (_ratings[recipeId].Sum() + recipe.AverageRating * 20) / recipe.RatingCount, 1);
    }

    public void SubmitRecipe(RecipeSubmission submission)
    {
        var newId = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(new Recipe
        {
            Id = newId,
            Title = submission.Title,
            Category = submission.Category,
            Description = $"A community-submitted recipe for {submission.Title}.",
            Ingredients = submission.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries).ToList(),
            Steps = submission.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries).ToList(),
            AverageRating = 0,
            RatingCount = 0
        });
    }
}

