@page "/"

<PageTitle>Recipe Community - Home</PageTitle>

<div class="container">
    <div class="hero">
        <h1>🍳 Recipe Community</h1>
        <p class="lead">Discover and share delicious recipes from around the world</p>
    </div>

    <h2>Browse by Category</h2>
    <div class="category-grid">
        @foreach (var category in Categories)
        {
            <a href="/category/@category" class="category-card">
                <span class="category-icon">@GetCategoryIcon(category)</span>
                <h3>@category</h3>
            </a>
        }
    </div>

    <div class="cta-section">
        <h2>Have a recipe to share?</h2>
        <p>Join our community and submit your favorite recipes!</p>
        <a href="/submit" class="btn-submit">Submit a Recipe</a>
    </div>
</div>

@code {
    [Inject] private RecipeCommunity.Services.RecipeService RecipeService { get; set; } = default!;

    private IReadOnlyList<string> Categories { get; set; } = [];

    protected override void OnInitialized()
    {
        Categories = RecipeService.GetCategories();
    }

    private static string GetCategoryIcon(string category) => category switch
    {
        "Italian" => "🍝",
        "Indian" => "🍛",
        "Mexican" => "🌮",
        "Asian" => "🥢",
        "Desserts" => "🍰",
        _ => "🍽️"
    };
}

@page "/category/{CategoryName}"

<PageTitle>@CategoryName Recipes - Recipe Community</PageTitle>

<div class="container">
    <nav class="breadcrumb">
        <a href="/">Home</a> &rsaquo; <span>@CategoryName</span>
    </nav>

    <h1>@GetCategoryIcon(CategoryName) @CategoryName Recipes</h1>

    @if (Recipes.Count == 0)
    {
        <p>No recipes found in this category.</p>
    }
    else
    {
        <div class="recipe-grid">
            @foreach (var recipe in Recipes)
            {
                <a href="/recipe/@recipe.Id" class="recipe-card">
                    <h3>@recipe.Title</h3>
                    <p>@recipe.Description</p>
                    <div class="recipe-meta">
                        <span class="stars">@GetStars(recipe.AverageRating)</span>
                        <span class="rating-count">(@recipe.RatingCount ratings)</span>
                    </div>
                </a>
            }
        </div>
    }
</div>

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;
    [Inject] private RecipeCommunity.Services.RecipeService RecipeService { get; set; } = default!;

    private IReadOnlyList<RecipeCommunity.Models.Recipe> Recipes { get; set; } = [];

    protected override void OnInitialized()
    {
        Recipes = RecipeService.GetByCategory(CategoryName);
    }

    private static string GetStars(double rating)
    {
        var full = (int)Math.Floor(rating);
        var half = rating - full >= 0.5 ? 1 : 0;
        var empty = 5 - full - half;
        return new string('★', full) + (half > 0 ? "½" : "") + new string('☆', empty);
    }

    private static string GetCategoryIcon(string category) => category switch
    {
        "Italian" => "🍝",
        "Indian" => "🍛",
        "Mexican" => "🌮",
        "Asian" => "🥢",
        "Desserts" => "🍰",
        _ => "🍽️"
    };
}

@page "/recipe/{Id:int}"

<PageTitle>@(Recipe?.Title ?? "Recipe") - Recipe Community</PageTitle>

<div class="container">
    <nav class="breadcrumb">
        <a href="/">Home</a> &rsaquo;
        <a href="/category/@Recipe?.Category">@Recipe?.Category</a> &rsaquo;
        <span>@Recipe?.Title</span>
    </nav>

    @if (Recipe is null)
    {
        <p>Recipe not found.</p>
    }
    else
    {
        <article class="recipe-detail">
            <h1>@Recipe.Title</h1>
            <p class="recipe-description">@Recipe.Description</p>

            <RecipeCommunity.Components.Shared.StarRating RecipeId="Recipe.Id" CurrentRating="Recipe.AverageRating" RatingCount="Recipe.RatingCount" />

            <section class="ingredients-section">
                <h2>🥘 Ingredients</h2>
                <ul>
                    @foreach (var ingredient in Recipe.Ingredients)
                    {
                        <li>@ingredient</li>
                    }
                </ul>
            </section>

            <section class="steps-section">
                <h2>📝 Steps</h2>
                <ol>
                    @foreach (var step in Recipe.Steps)
                    {
                        <li>@step</li>
                    }
                </ol>
            </section>
        </article>
    }
</div>

@code {
    [Parameter] public int Id { get; set; }
    [Inject] private RecipeCommunity.Services.RecipeService RecipeService { get; set; } = default!;

    private RecipeCommunity.Models.Recipe? Recipe { get; set; }

    protected override void OnInitialized()
    {
        Recipe = RecipeService.GetById(Id);
    }
}

@rendermode InteractiveServer

<div class="star-rating-widget">
    <div class="stars-interactive">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <button class="star-btn @(star <= HoverRating ? "hover" : star <= SelectedRating ? "selected" : "")"
                    @onmouseover="() => HoverRating = star"
                    @onmouseout="() => HoverRating = 0"
                    @onclick="() => SubmitRating(star)"
                    aria-label="Rate @star stars">
                ★
            </button>
        }
    </div>
    <span class="rating-info">
        @if (SelectedRating > 0)
        {
            <span class="your-rating">You rated: @SelectedRating/5</span>
        }
        else
        {
            <span>@CurrentRating.ToString("0.0") avg (@RatingCount ratings) — Click to rate!</span>
        }
    </span>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentRating { get; set; }
    [Parameter] public int RatingCount { get; set; }
    [Inject] private RecipeCommunity.Services.RecipeService RecipeService { get; set; } = default!;

    private int HoverRating { get; set; }
    private int SelectedRating { get; set; }

    private void SubmitRating(int stars)
    {
        SelectedRating = stars;
        RecipeService.AddRating(RecipeId, stars);
        var recipe = RecipeService.GetById(RecipeId);
        if (recipe is not null)
        {
            CurrentRating = recipe.AverageRating;
            RatingCount = recipe.RatingCount;
        }
    }
}

@page "/submit"
@rendermode InteractiveServer

<PageTitle>Submit a Recipe - Recipe Community</PageTitle>

<div class="container">
    <nav class="breadcrumb">
        <a href="/">Home</a> &rsaquo; <span>Submit Recipe</span>
    </nav>

    <h1>📤 Submit a Recipe</h1>
    <p>Share your favorite recipe with the community!</p>

    @if (Submitted)
    {
        <div class="success-message">
            <h2>✅ Recipe Submitted!</h2>
            <p>Thank you for sharing "<strong>@Submission.Title</strong>" with the community.</p>
            <a href="/">Back to Home</a>
        </div>
    }
    else
    {
        <EditForm Model="Submission" OnValidSubmit="HandleSubmit" class="recipe-form">
            <DataAnnotationsValidator />

            <div class="form-group">
                <label for="title">Recipe Title</label>
                <InputText id="title" @bind-Value="Submission.Title" placeholder="e.g., Grandma's Apple Pie" />
            </div>

            <div class="form-group">
                <label for="category">Category</label>
                <InputSelect id="category" @bind-Value="Submission.Category">
                    <option value="">-- Select a category --</option>
                    <option value="Italian">Italian</option>
                    <option value="Indian">Indian</option>
                    <option value="Mexican">Mexican</option>
                    <option value="Asian">Asian</option>
                    <option value="Desserts">Desserts</option>
                    <option value="Other">Other</option>
                </InputSelect>
            </div>

            <div class="form-group">
                <label for="ingredients">Ingredients (one per line)</label>
                <InputTextArea id="ingredients" @bind-Value="Submission.Ingredients" rows="6"
                    placeholder="2 cups flour&#10;1 cup sugar&#10;3 large apples..." />
            </div>

            <div class="form-group">
                <label for="steps">Steps (one per line)</label>
                <InputTextArea id="steps" @bind-Value="Submission.Steps" rows="6"
                    placeholder="Preheat oven to 350°F.&#10;Mix dry ingredients.&#10;..." />
            </div>

            <button type="submit" class="btn-submit"
                    disabled="@(string.IsNullOrWhiteSpace(Submission.Title) || string.IsNullOrWhiteSpace(Submission.Category))">
                Submit Recipe
            </button>
        </EditForm>
    }
</div>

@code {
    [Inject] private RecipeCommunity.Services.RecipeService RecipeService { get; set; } = default!;

    private RecipeCommunity.Models.RecipeSubmission Submission { get; set; } = new();
    private bool Submitted { get; set; }

    private void HandleSubmit()
    {
        if (string.IsNullOrWhiteSpace(Submission.Title) || string.IsNullOrWhiteSpace(Submission.Category))
            return;

        RecipeService.SubmitRecipe(Submission);
        Submitted = true;
    }
}

